using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DrawSpecificTierCustomName", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/DrawSpecificTierCustomName", order = 0)]
public class DrawSpecificTierCustomName : CustomBattleActionName
{
	public override string GetActionName(BattleAction battleAction)
	{
		if (battleAction is DrawAction)
		{
			DrawAction drawAction = battleAction as DrawAction;
			return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(battleAction.BaseBattleActionData.ActionIDName), drawAction.DiceSpecificTier.GetLocalizedDiceTier());
		}
		if (battleAction is ApplyEffectDrawDieAction)
		{
			ApplyEffectDrawDieAction applyEffectDrawDieAction = battleAction as ApplyEffectDrawDieAction;
			Debug.Log(applyEffectDrawDieAction.DrawAction.BaseBattleActionData.ActionIDName);
			Debug.Log(applyEffectDrawDieAction.DrawAction.DiceSpecificTier.GetLocalizedDiceTier());
			return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(applyEffectDrawDieAction.DrawAction.BaseBattleActionData.ActionIDName), applyEffectDrawDieAction.DrawAction.DiceSpecificTier.GetLocalizedDiceTier());
		}
		return "";
	}
}
